import hashlib, json, sys
from pathlib import Path
root = Path(sys.argv[1])
graph = json.loads((root / ".dev-graph/state/graph.json").read_text(encoding="utf-8"))
findings = []
for node in graph["nodes"]:
    nid = node["graph_node_id"]
    lineage = node.get("source_lineage") or {}
    if lineage.get("origin_kind") != "system-spec-harness":
        continue
    sp = lineage.get("source_path")
    if not sp:
        findings.append((nid, "lineage_source_path_missing", "source_lineage.source_path is null"))
    else:
        target = root / sp
        if not target.is_file():
            findings.append((nid, "lineage_source_unresolved", f"source_lineage.source_path -> {sp} (missing in caller repo)"))
        else:
            digest = hashlib.sha256(target.read_bytes()).hexdigest()
            if digest != lineage.get("source_digest"):
                findings.append((nid, "lineage_digest_mismatch", f"{sp}: {digest} != {lineage.get('source_digest')}"))
    ev = (node.get("confirmation_evidence") or {}).get("evidence_ref")
    if ev and not (root / ev).exists():
        findings.append((nid, "evaluator_evidence_unresolved", f"confirmation_evidence.evidence_ref -> {ev} (missing in caller repo)"))
ss = root / "system-spec"
print(json.dumps({
    "system_spec_root_exists": ss.exists(),
    "nodes_claiming_harness_origin": [n["graph_node_id"] for n in graph["nodes"] if (n.get("source_lineage") or {}).get("origin_kind") == "system-spec-harness"],
    "lineage_findings": [{"node": a, "code": b, "detail": c} for a, b, c in findings],
    "lineage_integrity": "BROKEN" if findings else "OK",
}, ensure_ascii=False, indent=2))
sys.exit(1 if findings else 0)
